// CSD_RATIONALE_BEGIN
// Lazy-close constrained CSD for symbolic GSM (attempt 3).
//
// Root-cause analysis of attempt 2 failures (from feedback):
//
// 1. TINY SPANS (38/49, cluster mode_B): Phase 3 checked IsCompletePrefix at
//    the TOP of the inner loop and immediately called CloseConstrainedSpan as
//    soon as the parser accepted a single-variable prefix (e.g. "n1"). This
//    closed the span after exactly one token even though the correct answer
//    is "n1 + n1*mult + n2 + n3".
//
// 2. UNTERMINATED SPANS (6/49, cluster mode_F/G): When AdaptiveConstrainedStep
//    returned eosToken inside the constrained span, the previous strategy did
//    `break` without emitting ">>". This left the span open and produced an
//    unterminated segment that scored zero.
//
// Fixes applied here:
//
// A. REMOVE the eager `IsCompletePrefix → CloseConstrainedSpan` path from the
//    inner constrained loop entirely. Generate tokens under hard parser control
//    until the model signals EOS or the budget runs out. This lets the model
//    produce the full expression it was computing in its reasoning text.
//
// B. On EOS inside the span: call RollbackConstrainedToComplete, then
//    CloseConstrainedSpan before breaking. This converts every EOS-inside-span
//    case into a properly closed span.
//
// C. After the main loop, if the span is still open and budget remains, do
//    one final rollback-to-complete + close.
//
// D. Keep Phase 1 free reasoning capped at freeBudget = maxSteps - 200 so
//    Phase 3 always has at least 200 steps for the expression and close.
//
// E. Task guidance stresses COMPLETE multi-variable expressions, not single
//    variable answers.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedStep outside):
//     The implication is vacuously true while !insideConstrainedOut. On the
//     branch where RenderedEndsWith(generated,"<<") flips insideConstrainedOut
//     true, we set currentConstrainedOut := [], which satisfies
//     parser.IsValidPrefix([]) by the method precondition. State otherwise
//     unchanged, so no violation.
//
//   Phase 2 (OpenConstrainedSpan):
//     Appends "<<" and resets currentConstrainedOut := []. Same argument as
//     the << detection branch above; validity holds.
//
//   Phase 3 token path (AdaptiveConstrainedStep + AppendConstrainedToken):
//     AdaptiveConstrainedStep returns either eosToken or a token t such that
//     parser.IsValidPrefix(currentConstrainedOut + [t]). AppendConstrainedToken
//     updates currentConstrainedOut to that valid extension. Validity preserved.
//
//   Phase 3 EOS path (RollbackConstrainedToComplete + CloseConstrainedSpan):
//     RollbackConstrainedToComplete postcondition guarantees
//     parser.IsValidPrefix(rc) for the returned rc. CloseConstrainedSpan (when
//     called) sets insideConstrainedOut := false and currentConstrainedOut := [],
//     making the implication vacuously true. If close is skipped (not complete
//     or no budget), insideConstrainedOut stays true and rc is valid. Break
//     exits the loop; invariant holds at exit.
//
//   Phase 4 (emergency rollback + close):
//     Same argument as Phase 3 EOS path. The outer guard ensures steps < maxSteps,
//     so the close budget is positive.
//
// progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 1: Each UnconstrainedStep costs 1 step and appends at most 1 visible
//     token (non-EOS). Bound |generated| <= |generatedPrefix| + steps preserved
//     every iteration.
//
//   Phase 2: OpenConstrainedSpan appends exactly "<<" (1 token) and steps += 1.
//     Bound preserved.
//
//   Phase 3 token path: AdaptiveConstrainedStep costs 1 step (steps += 1);
//     AppendConstrainedToken appends 1 visible token. Net: 1 step, 1 token.
//     Bound preserved.
//
//   Phase 3 EOS path: AdaptiveConstrainedStep costs 1 step (steps += 1); 0
//     visible tokens from it. RollbackConstrainedToComplete can only SHRINK
//     generated (removes suffix tokens), so |generated| can only decrease or
//     stay. CloseConstrainedSpan appends ">>" (1 token) and costs 1 step
//     (steps += 1), guarded by steps < maxSteps at that point. Net over both
//     increments: at most 2 steps, at most 1 visible token (the ">>" only;
//     rollback removed some). Bound preserved since |gen_after_close| <=
//     |gen_before_rollback| + 1 <= |genPrefix| + (steps_before_eos_step) + 1
//     <= |genPrefix| + steps_after_close.
//
//   Phase 4: 0 steps for rollback; 1 step and ">>" for close, guarded by
//     steps < maxSteps. After: steps <= maxSteps, |generated| grows by 1,
//     bound holds by identical arithmetic.
//
//   cost = steps <= maxSteps in all paths satisfies `cost <= maxSteps`.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math word problem step by step using the symbolic variable names " +
  "exactly as given in the problem. " +
  "Identify ALL quantities and how they combine. " +
  "Write intermediate sub-results inside << >> as you go. " +
  "At the very end, output the single COMPLETE symbolic expression for the " +
  "final answer inside << >>. " +
  "The final expression MUST combine all relevant variables with arithmetic " +
  "operations (+, -, *, /, //, %, int()); do not write just one variable name.");

var steps: nat := 0;
// Reserve at least 200 steps for Phase 3 constrained expression generation
var freeBudget: nat := if maxSteps > 200 then maxSteps - 200 else maxSteps / 2;

// Phase 1: Unconstrained reasoning up to freeBudget steps; watch for <<
while steps < freeBudget && !insideConstrainedOut
  invariant 0 <= steps <= freeBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// Phase 2: If no natural << appeared, force the span open
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained token generation.
// KEY FIX: Do NOT check IsCompletePrefix here to proactively close.
// Let the model generate the full expression until it emits EOS.
// On EOS, roll back to the last complete parse and close the span.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.AdaptiveConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut,
    validTokenGroups, 4.0, 12, eosToken
  );
  steps := steps + 1;
  if next == eosToken {
    // Model signals end of expression.
    // Roll back to the last complete parse point, then emit >>
    var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
    generated := rg;
    currentConstrainedOut := rc;
    if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    }
    break;
  }
  // Append the parser-valid token to both generated and currentConstrainedOut
  var ag, ai, ac := helpers.AppendConstrainedToken(
    lm, parser, generated, currentConstrainedOut, next
  );
  generated := ag;
  insideConstrainedOut := ai;
  currentConstrainedOut := ac;
}

// Phase 4: Emergency close — if the span is still open after the loop
// (budget exhausted without EOS), roll back to the last complete prefix
// and close with any remaining budget.
if insideConstrainedOut && steps < maxSteps {
  var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
  generated := rg;
  currentConstrainedOut := rc;
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  }
}

cost := steps;

